async function request(route,method='GET',body,canRefresh=true){
 if(window.GridSyncDemo?.enabled)return window.GridSyncDemo.request(route,method,body);
 const opts={method,credentials:'same-origin',headers:method==='GET'?{}:{'Content-Type':'application/json','X-GridSync-Request':'1'},signal:AbortSignal.timeout(20000)};if(body!==undefined)opts.body=JSON.stringify(body);
 const response=await fetch('/api'+route,opts);
 if(response.status===401&&canRefresh&&!route.startsWith('/auth/')){
  refreshing??=request('/auth/refresh','POST',{},false).finally(()=>refreshing=null);
  try{await refreshing;}catch{if(document.body.dataset.page!=='login')location.replace('/login');throw Error('Please sign in to continue.');}
  return request(route,method,body,false);
 }
 const data=await response.json().catch(()=>({error:'Unexpected server response. Check the deployment and API configuration.'}));
 if(!response.ok){const error=Error(data.error||'The request failed.');error.status=response.status;throw error;}return data;
}
function showModal(title,html){$('#modal-title').textContent=title;$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
