function input(name,label,value='',type='text',attrs='',full=false){return `<label class="${full?'full':''}">${label}<input name="${name}" type="${type}" value="${esc(value??'')}" ${attrs}></label>`;}
function select(name,label,choices,value='',full=false){return `<label class="${full?'full':''}">${label}<select name="${name}" required>${choices.map(([id,text])=>`<option value="${esc(id)}" ${String(value)===String(id)?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;}
function openForm(title,fields,route,method='POST',note='',transform=x=>x){
 const requestKey=crypto.randomUUID();
 showModal(title,`${note?`<p class="form-note">${esc(note)}</p>`:''}<form id="edit-form" class="form-grid">${fields}<div class="full form-error" id="form-error" role="alert"></div><button class="button dark full" type="submit">${route==='/reservations'?'Continue to fake payment':'Save changes'} ↗</button></form>`);
  $('#edit-form').onsubmit=async e=>{e.preventDefault();const form=e.target,submit=form.querySelector('[type=submit]');submit.disabled=true;$('#form-error').textContent='';let result;
 try{const payload=transform(Object.fromEntries(new FormData(form)));if(route==='/reservations')payload.idempotency_key=requestKey;result=await request(route,method,payload);}catch(error){$('#form-error').textContent=error.message;submit.disabled=false;return;}
 if(route==='/reservations'){try{tab='reservations';await load();checkout(result.checkout_id,true);}catch(error){if($('#form-error'))$('#form-error').textContent='Reservation is not confirmed. '+error.message;submit.disabled=false;}return result;}
 if(route==='/me'){me=result;$('#welcome').textContent=`Welcome, ${me.full_name}. Your connected workspace is ready.`;}
 $('#modal').close();toast('Saved successfully.');try{await load();}catch(error){$('#workspace-error').hidden=false;$('#workspace-error').textContent='Saved, but refreshing failed. Use Refresh to retrieve the latest records. '+error.message;}return result;};
}
function vehicleForm(id){const v=id?find('vehicles',id):{};openForm(id?'Update your vehicle.':'Your next journey starts here.',input('license_plate','Registration',v.license_plate,'text','required minlength="3" maxlength="20" pattern="[A-Za-z0-9][A-Za-z0-9 -]{2,19}"')+input('make','Make',v.make,'text','required maxlength="80"')+input('model','Model',v.model,'text','required maxlength="80"')+select('vehicle_type','Vehicle type',[['car','Car'],['van','Van'],['bus','Bus'],['truck','Truck'],['motorcycle','Motorcycle']],v.vehicle_type||'car')+input('battery_capacity_kwh','Battery capacity (kWh)',v.battery_capacity_kwh,'number','min="0.1" step="0.1"')+input('max_charge_rate_kw','Maximum charge power (kW)',v.max_charge_rate_kw,'number','min="0.1" step="0.1"')+`<fieldset class="full"><legend>Supported connectors</legend><div class="checkbox-list">${['CCS2','Type2','CHAdeMO','NACS'].map(c=>`<label><input type="checkbox" name="connector_${c}" ${v.connector_types?.includes(c)?'checked':''}>${c}</label>`).join('')}</div></fieldset>`,id?'/vehicles/'+id:'/vehicles',id?'PATCH':'POST','Only select connector types supported by this vehicle. Unknown battery capacity and charging power may be left blank.',p=>({...p,connector_types:['CCS2','Type2','CHAdeMO','NACS'].filter(c=>p['connector_'+c]==='on'),battery_capacity_kwh:p.battery_capacity_kwh||null,max_charge_rate_kw:p.max_charge_rate_kw||null}));}
