 (kind==='reservation'?input('start_time','Start',localTime(3600000),'datetime-local','required')+input('end_time','End',localTime(7200000),'datetime-local','required'):
 select('meter_source','Meter source',[['simulated','Simulated readings'],['manual','Manual meter readings']], 'simulated',true)+(r?`<input type="hidden" name="reservation_id" value="${r.reservation_id}">`:input('scheduled_at','Schedule (optional)','', 'datetime-local','',true)));
