 'session-complete':id=>openForm('Complete and generate invoice.',input('idle_minutes','Idle minutes',0,'number','required min="0" step="1"',true),`/sessions/${id}/complete`,'POST','Record the final meter reading first. Completing locks the session and generates one invoice from the saved readings and tariff.'),
 'session-cancel':id=>openForm('Cancel this request.',input('reason','Reason','','text','required minlength="3" maxlength="1000"',true),`/sessions/${id}/cancel`),
 'session-fail':id=>openForm('Report a charging failure.',input('reason','Failure reason','','text','required minlength="3" maxlength="1000"',true),`/sessions/${id}/fail`,'POST','The session stops and releases grid capacity. Recorded energy is invoiced if greater than zero.'),
 'invoice-details':invoiceDetails,'payment-details':paymentDetails,'checkout':id=>checkout(id),
